    NA_MED varchar2(300 char) not null,
    NA_ALIAS varchar2(300 char),
    SD_MED_TYPE varchar2(32 char) not null,
    DOSE_FORM varchar2(64 char),
    PREPARATION_SPEC varchar2(300 char),
    PREPARATION_UNIT varchar2(64 char),
    QTY_STRENGTH_VAL number(28,8),
    STRENGTH_UNIT varchar2(64 char),
