    FG_PRESCRIPTION_DRUG number(1) default 0 not null,
    FG_ESSENTIAL_DRUG number(1) default 0 not null,
    FG_ANTIMICROBIAL number(1) default 0 not null,
    SD_ANTIMICROBIAL_LEVEL varchar2(64 char),
    FG_SKIN_TEST_REQUIRED number(1) default 0 not null,
    QTY_DEFAULT_DOSE number(28,8),
    DEFAULT_DOSE_UNIT varchar2(64 char),
    DEFAULT_ROUTE varchar2(64 char),
    DEFAULT_FREQUENCY varchar2(64 char),
    FG_CHRONIC_DISEASE_DRUG number(1) default 0 not null,
    FG_SINGLE_ORDER number(1) default 1 not null,
    SD_STATUS varchar2(32 char) not null,
    DT_CREATED timestamp with time zone not null,
    ID_USER_CREATED number(19),
    DT_UPDATED timestamp with time zone not null,
    ID_USER_UPDATED number(19),
    ID_ITEM_TYPE number(19) not null,
    ID_ITEM_MASTER number(19),
    ID_ORDER_FREQ_DEFAULT number(19),
    ID_CONCEPT_DEFAULT_ROUTE number(19),
    constraint PK_BD_MED_PK primary key (ID_MED),
    constraint UK_BD_MED_MEDICATION_TENANT_ID unique (ID_TNT, ID_MED),
    constraint UK_BD_MED_MEDICATION_CODE unique (ID_TNT, CD_MED),
    constraint CK_BD_MED_MEDICATION_FLAGS check (FG_PRESCRIPTION_DRUG in (0, 1) and FG_ESSENTIAL_DRUG in (0, 1)
        and FG_ANTIMICROBIAL in (0, 1) and FG_SKIN_TEST_REQUIRED in (0, 1)
        and FG_CHRONIC_DISEASE_DRUG in (0, 1) and FG_SINGLE_ORDER in (0, 1)),
    constraint CK_BD_MED_MEDICATION_DEFAULT_D check ((QTY_DEFAULT_DOSE is null and DEFAULT_DOSE_UNIT is null) or
    (QTY_DEFAULT_DOSE is not null and QTY_DEFAULT_DOSE > 0 and DEFAULT_DOSE_UNIT is not null)),
    constraint CK_BD_MED_MEDICATION_ANTIMICRO check (FG_ANTIMICROBIAL = 1 or SD_ANTIMICROBIAL_LEVEL is null),
    FG_ANTIMICROBIAL_OUTPATIENT number(1) default 0 not null,
    FG_ANTIMICROBIAL_CONSULT number(1) default 0 not null,
    FG_ANTIMICROBIAL_EMERGENCY number(1) default 0 not null,
    QTY_ANTIMICROBIAL_MAX_DAYS number(10),
