    SD_CURRENT_OPERATION varchar2(32 char) not null,
    CD_REGION varchar2(64 char) not null,
    CD_INS_TYPE varchar2(64 char) not null,
    NA_PAYER_SNAP varchar2(300 char) not null,
    CD_ORG varchar2(128 char) not null,
    CD_DEPT varchar2(128 char) not null,
    CD_PRACT varchar2(128 char) not null,
