create table RHN_SUP_INP_MED_SUPPLY_BATCH (
    ID_INP_MED_SUPPLY_BATCH number(19),
    REVISION number(19) default 0 not null,
    ID_TNT number(19) not null,
    ID_ORG number(19) not null,
    ID_STOCK_SITE number(19) not null,
    ID_DEPT_NURS_UNIT number(19) not null,
