            and DES_CANCEL_REASON is null)
        or (SD_STATUS = 'CANCELLED' and ACTIVE_SLOT is null and DT_CANCELLED is not null
            and ID_USER_CANCELLED is not null and DES_CANCEL_REASON is not null))
);

