    QTY_ON_HAND number(28,8) not null,
    QTY_RESERVED number(28,8) not null,
    QTY_FROZEN number(28,8) not null,
    QTY_AVAILABLE number(28,8) not null,
    PRICE_AVERAGE_UNIT_COST number(24,6),
