    constraint CK_SUP_INV_BAL_INV_BAL_STATUS check (SD_STOCK_STATUS in ('AVAILABLE', 'PENDING', 'QUARANTINE', 'DAMAGED', 'EXPIRED')),
    constraint CK_SUP_INV_BAL_INV_BAL_QUANTIT check (QTY_ON_HAND >= 0 and QTY_RESERVED >= 0 and QTY_FROZEN >= 0 and QTY_AVAILABLE = QTY_ON_HAND - QTY_RESERVED - QTY_FROZEN and QTY_AVAILABLE >= 0)
