    constraint CK_SUP_INV_PRICE_INV_PRICE_REV check (ID_INV_PRICE_ADJ_REVERSAL_OF is null or ID_INV_PRICE_ADJ_REVERSAL_OF <> ID_INV_PRICE_ADJ),
