    AMT_VAL_AFTER number(30,6) not null,
    AMT_ADJ number(30,6) not null,
    AMT_ROUNDING number(30,6) default 0 not null,
    ID_INV_VALUAT_ENTRY number(19),
    DT_CREATED timestamp with time zone not null,
