    SD_ISSUE_TYPE varchar2(32 char) not null,
    QTY_EXPECTED number(28,8) not null,
    QTY_ACTUAL number(28,8) not null,
    QTY_DIFFERENCE number(28,8) not null,
    SD_SEVERITY varchar2(16 char) not null,
    DES_INV_RECON_LINE varchar2(1000 char) not null,
    SD_VALUAT_BASIS varchar2(32 char),
    CD_CURRENCY varchar2(16 char),
    AMT_EXPECTED number(30,6),
    AMT_ACTUAL number(30,6),
    AMT_DIFFERENCE number(30,6),
    constraint PK_SUP_INV_RECON_LINE_PK primary key (ID_INV_RECON_LINE),
    constraint UK_SUP_INV_RECON_INV_REC_LINE_ unique (ID_TNT, ID_INV_RECON_LINE),
