    SD_PRIORITY varchar2(24 char) not null,
    NA_TITLE varchar2(200 char) not null,
    DES_SUM varchar2(500 char) not null,
    DES_CONTENT clob not null,
    FG_PINNED number(1,0) default 0 not null,
    SD_STATUS varchar2(24 char) not null,
