    SD_SCOPE_TYPE varchar2(24 char) not null,
    ID_SCOPE number(19,0),
    SCOPE_REFERENCE varchar2(128 char),
    CD_SCOPE varchar2(200 char) not null,
    SD_VAL_MODE varchar2(24 char) not null,
    JSON_VAL clob,
    SECRET_REF varchar2(500 char),
    FG_ACTIVE number(1,0) default 1 not null,
    REVISION number(19,0) default 0 not null,
    DT_CREATED timestamp with time zone not null,
    ID_USER_CREATED number(19,0) not null,
    DT_UPDATED timestamp with time zone not null,
    ID_USER_UPDATED number(19,0) not null,
