    REFERENCE_RANGE_HIGH number(28,8),
    CD_INTERPRETATION varchar2(32 char),
    CD_PERFORMER varchar2(64 char),
    NA_PERFORMER varchar2(100 char),
    DT_CREATED timestamp with time zone not null,
